// dashboard.js — web dashboard for NKR.bot
// Secure login (bcrypt + Mongo sessions + CSRF + rate limits + AES-256-GCM field encryption)
// Servers are linked to a web account with a one-time code generated by /dashboard in Discord.

import express from "express";
import session from "express-session";
import MongoStore from "connect-mongo";
import bcrypt from "bcryptjs";
import helmet from "helmet";
import rateLimit from "express-rate-limit";
import crypto from "node:crypto";
import { ChannelType } from "discord.js";
import { ObjectId } from "mongodb";

const BCRYPT_COST = 12;
const MAX_FAILED_LOGINS = 5;
const LOCK_MS = 15 * 60 * 1000;
const CODE_TTL_MS = 10 * 60 * 1000;

// ============================================================
// Crypto helpers
// ============================================================

// Passwords are HASHED (bcrypt, one-way) — never stored encrypted/reversible.
// Other sensitive fields (e.g. email) are ENCRYPTED at rest with AES-256-GCM.
function getKey() {
  const hex = process.env.ENCRYPTION_KEY;
  if (!hex || !/^[0-9a-fA-F]{64}$/.test(hex)) {
    throw new Error("ENCRYPTION_KEY must be 64 hex chars (32 bytes). Generate: node -e \"console.log(require('crypto').randomBytes(32).toString('hex'))\"");
  }
  return Buffer.from(hex, "hex");
}

export function encryptField(plain) {
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv("aes-256-gcm", getKey(), iv);
  const enc = Buffer.concat([cipher.update(String(plain), "utf8"), cipher.final()]);
  const tag = cipher.getAuthTag();
  return [iv, tag, enc].map(b => b.toString("base64")).join(":");
}

export function decryptField(payload) {
  const [iv, tag, enc] = payload.split(":").map(p => Buffer.from(p, "base64"));
  const decipher = crypto.createDecipheriv("aes-256-gcm", getKey(), iv);
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(enc), decipher.final()]).toString("utf8");
}

const sha256 = s => crypto.createHash("sha256").update(s).digest("hex");

// Called by the /dashboard slash command. Stores only a hash of the code; valid 10 minutes, one use.
export async function createLinkCode(db, guildId, discordUserId) {
  const col = db.collection("linkCodes");
  await col.deleteMany({ guildId });
  const code = crypto.randomBytes(5).toString("hex").toUpperCase(); // 10 chars
  await col.insertOne({
    codeHash: sha256(code),
    guildId,
    createdBy: discordUserId,
    expiresAt: new Date(Date.now() + CODE_TTL_MS)
  });
  return code;
}

// ============================================================
// HTML helpers (no client-side JS at all; strict CSP)
// ============================================================

const esc = s =>
  String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

