function page({ title, body, user, csrf, flash }) {
  const nav = user
    ? `<form method="post" action="/dashboard/logout"><input type="hidden" name="_csrf" value="${esc(csrf)}"><span class="muted">${esc(user.username)}</span> &nbsp; <button class="link" type="submit">Log out</button></form>`
    : `<span><a href="/dashboard/login">Log in</a> &nbsp; <a href="/dashboard/register">Register</a></span>`;
  const flashHtml = flash ? `<div class="${flash.type === "ok" ? "ok" : "err"}">${esc(flash.msg)}</div>` : "";
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} · NKR.bot</title><style>${CSS}</style></head><body><header><a href="/dashboard">🧠 NKR.bot Dashboard</a>${nav}</header><main>${flashHtml}${body}</main></body></html>`;
}


// ============================================================
// Settings schema — ONE source of truth for the form, validation AND bot defaults
// ============================================================
const WELCOME_DEFAULT = "Welcome {user} to **{server}**! You are member #{count}.";
const LEAVE_DEFAULT = "**{username}** has left {server}.";
const AI_DEFAULT = "You are a friendly Discord assistant. Keep answers concise.";

export const SETTINGS_SCHEMA = [
  {
    title: "🛡 Moderation",
    fields: [
      { key: "modLogChannelId", type: "channel", def: null, label: "Mod-log channel", help: "Where kicks, bans, softbans, mutes and warnings are posted." },
      { key: "dmOnAction", type: "bool", def: true, label: "DM members when they are warned / muted / kicked / banned" },
      { key: "softbanDeleteDays", type: "int", min: 0, max: 7, def: 1, label: "Softban: delete messages from the last N days", help: "Used when /softban is run without a number." },
      { key: "warnThreshold", type: "int", min: 0, max: 20, def: 0, label: "Auto-punish after this many warnings (0 = off)", help: "Triggers at every multiple, e.g. 3 = at 3, 6, 9 warnings." },
      { key: "warnAction", type: "select", def: "mute", label: "Auto-punishment", options: [{ value: "mute", label: "Mute (timeout)" }, { value: "kick", label: "Kick" }, { value: "ban", label: "Ban" }] },
      { key: "warnMuteMinutes", type: "int", min: 1, max: 40320, def: 60, label: "Auto-mute length (minutes)", help: "Only used when the auto-punishment is Mute. Max 28 days." }
    ]
  },
  {
    title: "👋 Welcome & leave",
    help: "Placeholders: {user} (mention), {username}, {server}, {count} (member count).",
    fields: [
      { key: "welcomeEnabled", type: "bool", def: false, label: "Send a welcome message when someone joins" },
      { key: "welcomeChannelId", type: "channel", def: null, label: "Welcome channel" },
      { key: "welcomeMessage", type: "textarea", def: WELCOME_DEFAULT, maxLen: 500, label: "Welcome message" },
      { key: "autoRoleId", type: "role", def: null, label: "Auto-role for new members", help: "The bot's own role must be ABOVE this role in Server Settings → Roles." },
      { key: "leaveEnabled", type: "bool", def: false, label: "Send a message when someone leaves" },
      { key: "leaveChannelId", type: "channel", def: null, label: "Leave channel" },
      { key: "leaveMessage", type: "textarea", def: LEAVE_DEFAULT, maxLen: 500, label: "Leave message" }
    ]
  },
  {
    title: "🚫 Auto-moderation",
    help: "Messages are deleted automatically. Members with Manage Messages or Administrator are exempt. The bot needs Manage Messages.",
    fields: [
      { key: "automodBlockInvites", type: "bool", def: false, label: "Delete Discord invite links" },
      { key: "automodBlockLinks", type: "bool", def: false, label: "Delete all links (includes invites)" },
      { key: "automodBlockedWords", type: "textarea", def: "", maxLen: 1000, label: "Blocked words", help: "Separate with commas or new lines. Whole words only, not case-sensitive." }
    ]
  },
  {
    title: "🤖 AI",
    fields: [
      { key: "aiEnabled", type: "bool", def: true, label: "AI replies enabled (! prefix, mentions, /ask)" },
      { key: "aiChannelId", type: "channel", def: null, label: "Only reply in this channel", help: "Leave empty to allow AI in every channel. DMs always work." },
      { key: "aiPersonality", type: "textarea", def: AI_DEFAULT, maxLen: 500, label: "AI personality / instructions" }
    ]
  },
  {
    title: "⭐ XP & levels",
    fields: [
      { key: "xpEnabled", type: "bool", def: false, label: "XP / leveling enabled", help: "Also enables /level and /leaderboard in this server." },
      { key: "xpPerMessage", type: "int", min: 1, max: 100, def: 10, label: "XP per message" },
      { key: "xpCooldownSeconds", type: "int", min: 0, max: 600, def: 0, label: "XP cooldown per member (seconds, 0 = none)", help: "A cooldown stops people farming XP by spamming." },
      { key: "levelUpChannelId", type: "channel", def: null, label: "Level-up announcement channel" }
    ]
  }
];

export const SETTINGS_DEFAULTS = Object.fromEntries(
  SETTINGS_SCHEMA.flatMap(s => s.fields).map(f => [f.key, f.def])
);

// Validates form input against the schema — never trusts the browser.
export function sanitizeSettings(body, guild) {
  const out = {};
  for (const f of SETTINGS_SCHEMA.flatMap(s => s.fields)) {
    const raw = body[f.key];
    switch (f.type) {
      case "bool":
        out[f.key] = raw === "1";
        break;
      case "int": {
        const n = parseInt(raw, 10);
        out[f.key] = Number.isInteger(n) ? Math.min(f.max, Math.max(f.min, n)) : f.def;
        break;
      }
      case "select":
        out[f.key] = f.options.some(o => o.value === String(raw)) ? String(raw) : f.def;
        break;
      case "channel": {
        const ch = raw ? guild.channels.cache.get(String(raw)) : null;
        out[f.key] = ch && ch.type === ChannelType.GuildText ? ch.id : null;
        break;
      }
      case "role": {
        const r = raw ? guild.roles.cache.get(String(raw)) : null;
        out[f.key] = r && r.id !== guild.id && !r.managed ? r.id : null;
        break;
      }
      default: {
        const t = String(raw ?? "").replace(/\r\n/g, "\n").trim().slice(0, f.maxLen || 200);
        out[f.key] = t || f.def || "";
      }
    }
  }
  return out;
}

export function renderField(f, cfg, guild) {
  const v = cfg[f.key] ?? f.def;
  const id = `f_${f.key}`;
  const hint = f.help ? `<div class="hint">${esc(f.help)}</div>` : "";
  switch (f.type) {
    case "bool":
      return `<div class="check"><input type="checkbox" id="${id}" name="${f.key}" value="1"${v ? " checked" : ""}><label for="${id}" style="margin:0">${esc(f.label)}</label></div>${hint}`;
    case "int":
      return `<label for="${id}">${esc(f.label)}</label><input type="number" id="${id}" name="${f.key}" min="${f.min}" max="${f.max}" value="${esc(v)}">${hint}`;
    case "select":
      return `<label for="${id}">${esc(f.label)}</label><select id="${id}" name="${f.key}">${f.options.map(o => `<option value="${esc(o.value)}"${o.value === v ? " selected" : ""}>${esc(o.label)}</option>`).join("")}</select>${hint}`;
    case "channel": {
      const opts = guild.channels.cache
        .filter(c => c.type === ChannelType.GuildText)
        .sort((a, b) => a.rawPosition - b.rawPosition)
        .map(c => `<option value="${esc(c.id)}"${c.id === v ? " selected" : ""}>#${esc(c.name)}</option>`)
        .join("");
      return `<label for="${id}">${esc(f.label)}</label><select id="${id}" name="${f.key}"><option value="">— none —</option>${opts}</select>${hint}`;
    }
    case "role": {
      const opts = guild.roles.cache
        .filter(r => r.id !== guild.id && !r.managed)
        .sort((a, b) => b.position - a.position)
        .map(r => `<option value="${esc(r.id)}"${r.id === v ? " selected" : ""}>@${esc(r.name)}</option>`)
        .join("");
      return `<label for="${id}">${esc(f.label)}</label><select id="${id}" name="${f.key}"><option value="">— none —</option>${opts}</select>${hint}`;
    }
    case "textarea":
      return `<label for="${id}">${esc(f.label)}</label><textarea id="${id}" name="${f.key}" maxlength="${f.maxLen || 500}">${esc(v)}</textarea>${hint}`;
    default:
      return `<label for="${id}">${esc(f.label)}</label><input type="text" id="${id}" name="${f.key}" maxlength="${f.maxLen || 200}" value="${esc(v)}">${hint}`;
  }
}

const csrfInput = csrf => `<input type="hidden" name="_csrf" value="${esc(csrf)}">`;

// ============================================================
// Router factory
// ============================================================

export function createDashboard({ client, db, mongoClient, getGuildConfig, setGuildConfig }) {
  if (!process.env.SESSION_SECRET || process.env.SESSION_SECRET.length < 32) {
    throw new Error("SESSION_SECRET must be set and at least 32 characters long.");
  }
  getKey(); // fail fast if ENCRYPTION_KEY is missing/invalid

  const users = db.collection("webUsers");
  const linkCodes = db.collection("linkCodes");
  const modActions = db.collection("modActions");
  const warnings = db.collection("warnings");

  users.createIndex({ username: 1 }, { unique: true }).catch(console.error);
  linkCodes.createIndex({ expiresAt: 1 }, { expireAfterSeconds: 0 }).catch(console.error);
  modActions.createIndex({ guildId: 1, time: -1 }).catch(console.error);

  // Used to keep login timing identical whether or not the username exists
  const DUMMY_HASH = bcrypt.hashSync("not-a-real-password", BCRYPT_COST);

  const router = express.Router();

  router.use(
    helmet({
      contentSecurityPolicy: {
        directives: {
          defaultSrc: ["'self'"],
          styleSrc: ["'self'", "'unsafe-inline'"],
          scriptSrc: ["'none'"],
          formAction: ["'self'"],
          frameAncestors: ["'none'"],
          imgSrc: ["'self'", "data:"]
        }
      }
    })
  );
  router.use(express.urlencoded({ extended: false, limit: "40kb" }));

  router.use(
    session({
      name: "nkr.sid",
      secret: process.env.SESSION_SECRET,
      resave: false,
      saveUninitialized: false,
      rolling: true,
      store: MongoStore.create({
        client: mongoClient,
        dbName: "nkrbot",
        collectionName: "webSessions",
        ttl: 60 * 60 * 24 * 7
      }),
      cookie: {
        httpOnly: true,
        sameSite: "lax",
        secure: "auto", // requires app.set("trust proxy", 1) behind Render
        maxAge: 1000 * 60 * 60 * 24 * 7,
        path: "/dashboard"
      }
    })
  );

  // CSRF token per session; every POST must echo it back
  router.use((req, res, next) => {
    if (!req.session.csrf) req.session.csrf = crypto.randomBytes(24).toString("hex");
    next();
  });

  function verifyCsrf(req, res, next) {
    const sent = Buffer.from(String(req.body?._csrf || ""));
    const real = Buffer.from(req.session.csrf || "");
    if (sent.length !== real.length || !crypto.timingSafeEqual(sent, real)) {
      return res.status(403).send(page({ title: "Error", body: `<div class="card"><h2>Invalid or expired form</h2><p>Go back, refresh the page and try again.</p></div>`, user: null, csrf: req.session.csrf }));
    }
    next();
  }

  const authLimiter = rateLimit({ windowMs: 15 * 60 * 1000, limit: 20, standardHeaders: true, legacyHeaders: false });
  const linkLimiter = rateLimit({ windowMs: 15 * 60 * 1000, limit: 10, standardHeaders: true, legacyHeaders: false });

  async function loadUser(req, res, next) {
    req.user = null;
    if (req.session.userId) {
      try {
        req.user = await users.findOne({ _id: new ObjectId(req.session.userId) });
      } catch { /* invalid id */ }
      if (!req.user) delete req.session.userId;
    }
    next();
  }
  router.use(loadUser);

  const render = (req, res, title, body, flash, status = 200) =>
    res.status(status).send(page({ title, body, user: req.user, csrf: req.session.csrf, flash }));

  const requireAuth = (req, res, next) => (req.user ? next() : res.redirect("/dashboard/login"));

  function requireGuild(req, res, next) {
    const guildId = req.params.id;
    const guild = client.guilds.cache.get(guildId);
    if (!/^\d{5,25}$/.test(guildId) || !req.user.guildIds?.includes(guildId) || !guild) {
      return render(req, res, "Not found", `<div class="card"><h2>Server not found</h2><p>It isn't linked to your account, or the bot isn't in it. <a href="/dashboard">Back</a></p></div>`, null, 404);
    }
    req.guild = guild;
    next();
  }

  // ---------- Register ----------
  router.get("/register", (req, res) => {
    if (req.user) return res.redirect("/dashboard");
    render(req, res, "Register", registerForm(req.session.csrf));
  });

  function registerForm(csrf) {
    return `<div class="card"><h2>Create account</h2>
<form method="post" action="/dashboard/register">${csrfInput(csrf)}
<label>Username (3-24 letters, numbers, underscore)</label><input type="text" name="username" required minlength="3" maxlength="24" autocomplete="username">
<label>Email (optional, stored encrypted)</label><input type="email" name="email" maxlength="120" autocomplete="email">
<label>Password (10-72 characters)</label><input type="password" name="password" required minlength="10" maxlength="72" autocomplete="new-password">
<label>Confirm password</label><input type="password" name="confirm" required minlength="10" maxlength="72" autocomplete="new-password">
<button type="submit">Register</button></form></div>`;
  }

  router.post("/register", authLimiter, verifyCsrf, async (req, res) => {
    const username = String(req.body.username || "").trim().toLowerCase();
    const email = String(req.body.email || "").trim();
    const password = String(req.body.password || "");
    const confirm = String(req.body.confirm || "");

    const fail = msg => render(req, res, "Register", registerForm(req.session.csrf), { type: "err", msg }, 400);

    if (!/^[a-z0-9_]{3,24}$/.test(username)) return fail("Username must be 3-24 characters: letters, numbers, underscore.");
    if (password.length < 10 || password.length > 72) return fail("Password must be 10-72 characters.");
    if (password !== confirm) return fail("Passwords do not match.");
    if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return fail("That email doesn't look valid.");

    try {
      await users.insertOne({
        username,
        passwordHash: await bcrypt.hash(password, BCRYPT_COST),
        emailEnc: email ? encryptField(email) : null,
        guildIds: [],
        failedLogins: 0,
        lockUntil: 0,
        createdAt: new Date()
      });
    } catch (err) {
      if (err.code === 11000) return fail("That username is taken.");
      console.error("register error:", err);
      return fail("Something went wrong. Try again.");
    }
    res.redirect("/dashboard/login?registered=1");
  });

  // ---------- Login / logout ----------
  const loginForm = csrf => `<div class="card"><h2>Log in</h2>
<form method="post" action="/dashboard/login">${csrfInput(csrf)}
<label>Username</label><input type="text" name="username" required maxlength="24" autocomplete="username">
<label>Password</label><input type="password" name="password" required maxlength="72" autocomplete="current-password">
<button type="submit">Log in</button></form></div>`;

  router.get("/login", (req, res) => {
    if (req.user) return res.redirect("/dashboard");
    const flash = req.query.registered ? { type: "ok", msg: "Account created. You can log in now." } : null;
    render(req, res, "Log in", loginForm(req.session.csrf), flash);
  });

  router.post("/login", authLimiter, verifyCsrf, async (req, res) => {
    const username = String(req.body.username || "").trim().toLowerCase();
    const password = String(req.body.password || "").slice(0, 72);
    const generic = { type: "err", msg: "Invalid username or password." };

    const user = await users.findOne({ username });

    if (user && user.lockUntil > Date.now()) {
      return render(req, res, "Log in", loginForm(req.session.csrf), { type: "err", msg: "Too many failed attempts. Try again in a few minutes." }, 429);
    }

    const ok = await bcrypt.compare(password, user?.passwordHash || DUMMY_HASH);
    if (!user || !ok) {
      if (user) {
        const failed = (user.failedLogins || 0) + 1;
        await users.updateOne(
          { _id: user._id },
          { $set: { failedLogins: failed >= MAX_FAILED_LOGINS ? 0 : failed, lockUntil: failed >= MAX_FAILED_LOGINS ? Date.now() + LOCK_MS : 0 } }
        );
      }
      return render(req, res, "Log in", loginForm(req.session.csrf), generic, 401);
    }

    await users.updateOne({ _id: user._id }, { $set: { failedLogins: 0, lockUntil: 0, lastLogin: new Date() } });

    // New session ID on login prevents session fixation
    req.session.regenerate(err => {
      if (err) return res.status(500).send("Session error");
      req.session.userId = user._id.toString();
      req.session.csrf = crypto.randomBytes(24).toString("hex");
      req.session.save(() => res.redirect("/dashboard"));
    });
  });

  router.post("/logout", verifyCsrf, (req, res) => {
    req.session.destroy(() => {
      res.clearCookie("nkr.sid", { path: "/dashboard" });
      res.redirect("/dashboard/login");
    });
  });

  // ---------- Home: linked servers + link form ----------
  router.get("/", requireAuth, (req, res) => {
    const linked = (req.user.guildIds || [])
      .map(id => client.guilds.cache.get(id))
      .filter(Boolean);

    const list = linked.length
      ? linked.map(g => `<tr><td>${esc(g.name)}</td><td style="text-align:right"><a href="/dashboard/guild/${esc(g.id)}">Manage</a></td></tr>`).join("")
      : `<tr><td class="muted">No servers linked yet.</td></tr>`;

    const flash = req.query.msg ? { type: req.query.t === "err" ? "err" : "ok", msg: String(req.query.msg).slice(0, 120) } : null;

    render(req, res, "Dashboard", `
<div class="card"><h2>Your servers</h2><table>${list}</table></div>
<div class="card"><h2>Link a server</h2>
<p class="muted">In Discord, run <b>/dashboard</b> in your server (needs Manage Server). Paste the one-time code here. Codes expire after 10 minutes.</p>
<form method="post" action="/dashboard/link">${csrfInput(req.session.csrf)}
<label>Link code</label><input type="text" name="code" required maxlength="10" autocomplete="off" style="text-transform:uppercase">
<button type="submit">Link server</button></form></div>`, flash);
  });

  router.post("/link", requireAuth, linkLimiter, verifyCsrf, async (req, res) => {
    const code = String(req.body.code || "").trim().toUpperCase();
    const doc = /^[0-9A-F]{10}$/.test(code) ? await linkCodes.findOneAndDelete({ codeHash: sha256(code), expiresAt: { $gt: new Date() } }) : null;
    const rec = doc?.value ?? doc; // driver v5 returns doc, v6 returns doc too
    if (!rec || !rec.guildId) return res.redirect("/dashboard?t=err&msg=" + encodeURIComponent("Invalid or expired code."));
    if (!client.guilds.cache.has(rec.guildId)) return res.redirect("/dashboard?t=err&msg=" + encodeURIComponent("The bot is no longer in that server."));
    await users.updateOne({ _id: req.user._id }, { $addToSet: { guildIds: rec.guildId } });
    res.redirect("/dashboard/guild/" + rec.guildId);
  });

  // ---------- Per-server settings ----------
  router.get("/guild/:id", requireAuth, requireGuild, async (req, res) => {
    const guild = req.guild;
    const cfg = await getGuildConfig(guild.id);

    const sections = SETTINGS_SCHEMA.map(sec =>
      `<div class="card"><h2>${esc(sec.title)}</h2>${sec.help ? `<p class="muted">${esc(sec.help)}</p>` : ""}${sec.fields.map(f => renderField(f, cfg, guild)).join("")}</div>`
    ).join("");

    const [actions, warnCount] = await Promise.all([
      modActions.find({ guildId: guild.id }).sort({ time: -1 }).limit(15).toArray(),
      warnings.countDocuments({ guildId: guild.id })
    ]);
    const rows = actions.length
      ? actions.map(a => `<tr><td>${esc(a.action)}</td><td>${esc(a.targetTag)}</td><td>${esc(a.moderatorTag)}</td><td>${esc((a.reason || "").slice(0, 80))}</td><td class="muted">${esc(new Date(a.time).toISOString().replace("T", " ").slice(0, 16))}</td></tr>`).join("")
      : `<tr><td colspan="5" class="muted">No actions recorded yet.</td></tr>`;

    const flash = req.query.saved ? { type: "ok", msg: "Settings saved." } : null;

    render(req, res, guild.name, `
<div class="card"><h2>${esc(guild.name)}</h2><p class="muted">${guild.memberCount} members · ${warnCount} warnings stored</p></div>
<form method="post" action="/dashboard/guild/${esc(guild.id)}/settings">${csrfInput(req.session.csrf)}${sections}<button class="save" type="submit">Save all settings</button></form>
<div class="card" style="margin-top:18px"><h2>Recent mod actions</h2><table><tr><th>Action</th><th>User</th><th>Moderator</th><th>Reason</th><th>When (UTC)</th></tr>${rows}</table></div>
<div class="card"><h2>Unlink</h2><p class="muted">Removes this server from your web account. Run /dashboard in Discord to link again.</p>
<form method="post" action="/dashboard/guild/${esc(guild.id)}/unlink">${csrfInput(req.session.csrf)}<button class="danger" type="submit">Unlink server</button></form></div>`, flash);
  });

  router.post("/guild/:id/settings", requireAuth, requireGuild, verifyCsrf, async (req, res) => {
    await setGuildConfig(req.guild.id, sanitizeSettings(req.body, req.guild));
    res.redirect(`/dashboard/guild/${req.guild.id}?saved=1`);
  });

  router.post("/guild/:id/unlink", requireAuth, requireGuild, verifyCsrf, async (req, res) => {
    await users.updateOne({ _id: req.user._id }, { $pull: { guildIds: req.guild.id } });
    res.redirect("/dashboard?msg=" + encodeURIComponent("Server unlinked."));
  });

  return router;
}